css:
:scope{display:block;width:100%}
.pw{--ink:#010A12;--bone:#EDE6D8;--sand:#BBAFA3;--mulberry:#5E3A3C;--clay:#8C5B46;--head:'Cormorant Garamond',serif;--body:'EB Garamond',serif;--label:'Montserrat',sans-serif;position:relative;font-family:var(--body);font-size:21px;line-height:1.5;font-weight:400;letter-spacing:0;-webkit-font-smoothing:antialiased;text-align:left;background:var(--bone);color:var(--ink)}
.pw *{box-sizing:border-box}
:where(.pw p,.pw h1,.pw h2,.pw h3){margin:0;padding:0}
:where(.pw p,.pw li,.pw h1,.pw h2,.pw h3){text-wrap:wrap}
:where(.pw h1,.pw h2,.pw h3){color:inherit}
:where(.pw){overflow-wrap:normal}
.in{max-width:1200px;margin:0 auto;padding:0 32px}
.pad{padding:160px 0}
.kick{margin:0;font-family:var(--label);font-weight:400;font-size:12px;letter-spacing:.32em;text-transform:uppercase;color:var(--mulberry)}
.rule{width:64px;height:1px;background:var(--clay);border:0;margin:28px 0 32px}
.pw h2{font-family:var(--head);font-weight:500;font-size:68px;line-height:1.04;letter-spacing:0;margin:0;text-wrap:balance;text-indent:.0147em}
.intro{margin:24px 0 0;max-width:36em}
.close{font-family:var(--head);font-style:italic;font-weight:500;font-size:34px;line-height:1.2;margin:72px 0 0}
.grid3{display:grid;grid-template-columns:repeat(3,1fr);grid-template-rows:auto auto auto auto;column-gap:48px;row-gap:0;margin-top:72px}
.grid3 .card{display:grid;grid-row:span 4;grid-template-rows:subgrid;align-content:start}
.card{border-top:1px solid var(--sand);padding-top:28px}
.card .ic{color:var(--mulberry);height:56px;display:flex;align-items:center}
.card .ic[data-icon=with]{color:var(--clay)}
.card .ic svg{display:none}
.card .ic[data-icon=circle] .i-circle,.card .ic[data-icon=over] .i-over,.card .ic[data-icon=with] .i-with{display:block}
.card .ic svg *{fill:none;stroke:currentColor;stroke-width:1.4}
.card .lab{margin:18px 0 0;font-family:var(--label);font-size:12px;letter-spacing:.3em;text-transform:uppercase}
.card .def{margin:14px 0 0;font-family:var(--head);font-weight:500;font-size:27px;line-height:1.25}
.card .b{margin:14px 0 0}
.js-rv .rv{opacity:0;transform:translateY(16px);transition:opacity 1.3s ease,transform 1.3s ease}
.js-rv .rv.on{opacity:1;transform:none}
.js-rv .d1{transition-delay:.12s}
@media (max-width:767px){.pw{font-size:19px}.in{padding:0 20px}.pad{padding:88px 0}.pw h2{font-size:40px}.close{font-size:27px;margin-top:44px}.grid3{grid-template-columns:1fr;gap:32px;margin-top:40px;row-gap:32px}.grid3 .card{grid-row:auto;display:block}.card .def{font-size:25px}}
@media (prefers-reduced-motion:reduce){.js-rv .rv{opacity:1;transform:none;transition:none}}
